changeSet.sql:
CREATE TABLE data.symbol_futures (
    id          serial4 NOT NULL,
    code        varchar(24) NOT NULL,
    is_observed bool DEFAULT false NOT NULL,
    ts_db       timestamp DEFAULT LOCALTIMESTAMP NOT NULL,
    CONSTRAINT symbol_futures_pkey PRIMARY KEY (id),
    CONSTRAINT uk_symbol_futures_code UNIQUE (code)
);
comment on table data.symbol_futures is 'All futures symbols';
comment on column data.symbol_futures.is_observed is 'Observed futures – data is retained longer in the futures_data table.';
comment on column data.symbol_futures.ts_db is 'When this symbol was save in dictionary';
